<?php
require __DIR__.'/_init.php';require_once ROOT.'/app/applications.php';
$app=(string)($_GET['app']??'turnos');$kinds=ds_app_kinds($app);require_permission($app.'.view');$scope=company_scope(isset($_GET['company'])?(string)$_GET['company']:null);$tid=$scope??tenant();$error='';$ok='';$issued='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{
 $tid=post_tenant();$action=(string)($_POST['action']??'');$rev=(int)($_POST['revision']??-1);
 if($action==='settings'){ds_app_save_settings($tid,$app,$rev,$_POST);$ok='Configuración guardada en el portal';}
 elseif(in_array($action,['save','delete'],true)){ds_app_entity($tid,$app,$rev,$_POST);$ok=$action==='delete'?'Elemento eliminado':'Elemento guardado';}
 elseif(in_array($action,['token','revoke'],true)){
  require_permission('integrations.manage');require_permission($app.'.manage');
  if(!is_super()&&$tid!==tenant())throw new RuntimeException('Empresa inválida');
  if($action==='token'){$label=trim((string)($_POST['label']??''));if($label===''||strlen($label)>120)throw new RuntimeException('Nombre de conexión requerido');$issued=bin2hex(random_bytes(32));execsql('INSERT INTO application_tokens(tenant_id,app,label,token_hash,created_by,created_at) VALUES(?,?,?,?,?,UTC_TIMESTAMP())',[$tid,$app,$label,hash('sha256',$issued),(int)auth()['id']]);$ok='Conexión de lectura creada';}
  else{execsql('UPDATE application_tokens SET revoked_at=UTC_TIMESTAMP() WHERE id=? AND tenant_id=? AND app=?',[(int)($_POST['id']??0),$tid,$app]);$ok='Conexión revocada';}
  log_event('application_connection_changed',['company'=>$tid,'app'=>$app,'action'=>$action]);
 }else throw new RuntimeException('Acción inválida');
}catch(Throwable $e){$error=$e instanceof PDOException?'No se pudo guardar: comprueba referencias y que la pantalla no esté asignada a otra aplicación':$e->getMessage();}}
$config=ds_app_config($tid,$app);$entities=dball('SELECT * FROM application_entities WHERE tenant_id=? AND app=? ORDER BY name',[$tid,$app]);$users=dball('SELECT id,name FROM users WHERE tenant_id=? AND is_active=1 ORDER BY name',[$tid]);$devices=dball('SELECT id,name FROM devices WHERE tenant_id=? ORDER BY name',[$tid]);$logos=dball("SELECT id,name FROM media WHERE (tenant_id=? OR is_shared=1) AND mime LIKE 'image/%' AND separator_key IS NULL ORDER BY name",[$tid]);
$tokens=can('integrations.manage')?dball('SELECT id,label,created_at,revoked_at FROM application_tokens WHERE tenant_id=? AND app=? ORDER BY id DESC',[$tid,$app]):[];
render(ds_apps()[$app].' · Configuración por empresa',function()use($app,$kinds,$tid,$error,$ok,$issued,$config,$entities,$users,$devices,$logos,$tokens){
 if($error)echo '<div class="alert alert-danger">'.h($error).'</div>';if($ok)echo '<div class="alert alert-success">'.h($ok).'</div>';
 echo '<p>Configura aquí la organización y sus equipos. Las reglas de turnos y de puntuación permanecen en sus aplicaciones. La conexión de la APK de pantalla y de los controles con esta configuración es la siguiente fase.</p><form method="get" class="ds-filters"><input type="hidden" name="app" value="'.h($app).'">'.str_replace('name="tenant_id"','name="company"',company_select($tid)).'<button class="btn btn-primary">Trabajar con esta empresa</button></form>';
 if($issued)echo '<div class="alert alert-warning">Copia ahora la clave de lectura; no volverá a mostrarse.<input readonly class="form-control" autocomplete="off" value="'.h($issued).'"></div>';
 $settings=$config['settings'];$common='<input type="hidden" name="tenant_id" value="'.$tid.'"><input type="hidden" name="revision" value="'.$config['revision'].'">';
 echo '<details class="card card-body mb-3"><summary>Identidad y preferencias · revisión '.$config['revision'].'</summary>';
 if(can($app.'.manage')){form_open();echo $common.'<input type="hidden" name="action" value="settings"><label>Nombre visible</label><input class="form-control mb-2" name="title" value="'.h($settings['title']).'" maxlength="160"><label>Logo de la empresa</label><select class="form-select mb-3" name="logo_media_id"><option value="0">Sin logo</option>';foreach($logos as $m)echo '<option value="'.$m['id'].'"'.((int)$settings['logo_media_id']===(int)$m['id']?' selected':'').'>'.h($m['name']).'</option>';echo '</select>';
 if($app==='turnos')echo '<label class="d-block"><input type="checkbox" name="request_whatsapp"'.($settings['request_whatsapp']?' checked':'').'> Solicitar WhatsApp en emisión de tickets</label><label class="d-block"><input type="checkbox" name="whatsapp_notifications_requested"'.($settings['whatsapp_notifications_requested']?' checked':'').'> Solicitar aviso al llamar por WhatsApp</label><p class="ds-hint">Preferencias guardadas. El envío aún requiere conectar el proveedor y los eventos de Turnos; activar esta casilla no envía mensajes.</p>';
 echo '<button class="btn btn-primary mt-2">Guardar preferencias</button></form>';}
 else echo '<p>'.h($settings['title']).'</p>';
 echo '</details>'; $modals='';
 foreach($kinds as $kind=>$spec){$rows=array_values(array_filter($entities,fn($e)=>$e['kind']===$kind));echo '<details class="card card-body mb-3"><summary><strong>'.h($spec['label']).'</strong> · '.count($rows).'</summary><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Nombre</th><th>Destino</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>';
 foreach($rows as $e){$parent='—';foreach($entities as $p)if($p['id']===$e['parent_id'])$parent=$p['name'];echo '<tr><td>'.h($e['name']).'</td><td>'.h($parent).'</td><td>'.((int)$e['enabled']?'Activo':'Inactivo').'</td><td>';if(can($app.'.manage')){echo '<button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#entity-'.$e['id'].'">Editar</button>';form_open();echo $common.'<input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="'.$e['id'].'"><input type="hidden" name="kind" value="'.h($kind).'"><button class="btn btn-sm btn-outline-danger" onclick="return confirm(&quot;¿Eliminar este elemento?&quot;)">Eliminar</button></form>';}echo '</td></tr>';}
 echo '</tbody></table></div>';if(can($app.'.manage'))echo '<button class="btn btn-primary align-self-start" data-bs-toggle="modal" data-bs-target="#new-'.$kind.'">Añadir '.h($spec['label']).'</button>';echo '</details>';
 if(!can($app.'.manage'))continue;
 foreach([['id'=>0,'name'=>'','parent_id'=>null,'user_id'=>null,'device_id'=>null,'enabled'=>1,'config_json'=>'{}'],...$rows] as $e){$vals=json_decode($e['config_json'],true)?:[];$dlg=$e['id']?'entity-'.$e['id']:'new-'.$kind;ob_start();echo '<div class="modal fade" id="'.$dlg.'" tabindex="-1"><div class="modal-dialog modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5>'.h($spec['label']).'</h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Cerrar"></button></div><div class="modal-body">';form_open();echo $common.'<input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="'.h($kind).'"><input type="hidden" name="id" value="'.$e['id'].'"><label>Nombre</label><input class="form-control mb-2" name="name" required maxlength="160" value="'.h($e['name']).'">';
 if($spec['parent']){$opts=[];foreach($entities as $p)if($p['kind']===$spec['parent'])$opts[$p['id']]=$p['name'];echo '<label>'.h($kinds[$spec['parent']]['label']).'</label>'.sel('parent_id',[''=>'Seleccionar']+$opts,(string)$e['parent_id']);}
 if(!empty($spec['user']))echo '<label>Usuario de esta empresa</label>'.sel('user_id',[''=>'Seleccionar']+array_column($users,'name','id'),(string)$e['user_id']);
 if(!empty($spec['device']))echo '<label>Pantalla de Digital Signage</label>'.sel('device_id',[''=>'Seleccionar']+array_column($devices,'name','id'),(string)$e['device_id']).'<p class="ds-hint">Una pantalla se vincula a Turnos o a Sports. La APK consumirá este enlace cuando se complete la siguiente fase.</p>';
 foreach($spec['fields'] as $key=>$label){echo '<label>'.h($label).'</label>';if(str_ends_with($key,'_id')){$refKind=match($key){'counter_id'=>'counter','tournament_id'=>'tournament',default=>'team'};$opts=[''=>'Sin asignar'];foreach($entities as $ref)if($ref['kind']===$refKind)$opts[$ref['id']]=$ref['name'];echo sel($key,$opts,(string)($vals[$key]??''));}else echo '<input class="form-control mb-2" name="'.h($key).'" maxlength="160" value="'.h((string)($vals[$key]??'')).'">';}
 echo '<label class="d-block mb-3"><input type="checkbox" name="enabled"'.((int)$e['enabled']?' checked':'').'> Activo</label><button class="btn btn-primary">Guardar</button></form></div></div></div></div>';$modals.=ob_get_clean();}
 }
 echo $modals.'<details class="card card-body"><summary>API de configuración y conexiones</summary><p>Consulta autenticada: <code>'.h(url('api-application-config.php?app='.$app)).'</code>. Devuelve revisión y configuración; no emite tickets ni modifica puntos.</p>';
 if(can($app.'.manage')&&can('integrations.manage')){form_open();echo '<input type="hidden" name="action" value="token"><input type="hidden" name="tenant_id" value="'.$tid.'"><label>Nombre de la conexión</label><input class="form-control mb-2" name="label" maxlength="120" required><button class="btn btn-primary">Crear clave de lectura</button></form>';foreach($tokens as $token){echo '<p>'.h($token['label']).' · '.h($token['revoked_at']?'Revocada':'Activa').'</p>';if(!$token['revoked_at']){form_open();echo '<input type="hidden" name="action" value="revoke"><input type="hidden" name="tenant_id" value="'.$tid.'"><input type="hidden" name="id" value="'.$token['id'].'"><button class="btn btn-sm btn-outline-danger">Revocar</button></form>';}}}
 echo '<p class="ds-hint">El equipo que consulte debe guardar su copia local para la futura operación sin Internet. Esta entrega no cambia aún los APK de Turnos y Sports.</p></details>';
});
